CREATE VIEW [dbo].[ViewIncassi3] AS  SELECT incassi.contatore1,incassi.contatore2,Incassi.IdIncasso,Incassi.Data,Locali.Nome,Incassi.Incasso,Incassi.IncassoNetto,Incassi.TotaleEntrate,Incassi.TotaleUscite,Incassi.Tasse,Incassi.rete,incassi.aams,Incassi.Bollettaincasso,Incassi.codicelocale,Incassi.prop as Proprieta,Incassi.associato as Associato,incassi.agente as Agente, Incassi.tipooggetto,Incassi.codiceoggetto,'Scheda' AS TipoMacchina,schede.nome as Modello,schede.matricola AS Matricola,Incassi.PartipologiaMonopoli,'' as identificativo  from incassi,schede,locali where locali.idlocale=incassi.codicelocale AND incassi.codiceoggetto=schede.idscheda and incassi.tipooggetto=1 UNION SELECT incassi.contatore1,incassi.contatore2,Incassi.IdIncasso,Incassi.Data,Locali.Nome,Incassi.Incasso,Incassi.IncassoNetto,Incassi.TotaleEntrate,Incassi.TotaleUscite,Incassi.Tasse,Incassi.rete,incassi.aams,Incassi.Bollettaincasso,Incassi.codicelocale,Incassi.prop as Proprieta,Incassi.associato as Associato,incassi.agente as Agente,Incassi.tipooggetto,Incassi.codiceoggetto,'Dedicato' AS TipoMacchina,dedicati.nome as Modello,dedicati.matricola as Matricola,Incassi.PartipologiaMonopoli,dedicati.identificativo  from incassi,dedicati,locali  where locali.idlocale=incassi.codicelocale AND incassi.codiceoggetto=dedicati.iddedicato and incassi.tipooggetto=2 UNION SELECT incassi.contatore1,incassi.contatore2,Incassi.IdIncasso,Incassi.Data,Locali.Nome,Incassi.Incasso,Incassi.IncassoNetto,Incassi.TotaleEntrate,Incassi.TotaleUscite,Incassi.Tasse,Incassi.rete,incassi.aams,Incassi.Bollettaincasso,Incassi.codicelocale,Incassi.prop as Proprieta,Incassi.associato as Associato,incassi.agente as Agente,Incassi.tipooggetto,Incassi.codiceoggetto,'Distributore' AS TipoMacchina,distribut.nome as Modello,distribut.matricola AS Matricola,Incassi.PartipologiaMonopoli ,'' as identificativo  from incassi,distribut,locali  where locali.idlocale=incassi.codicelocale AND incassi.codiceoggetto=distribut.iddistributore and incassi.tipooggetto=15
GO
